"""Host-observed UART measurements. No claim of FPGA/driver internal timing."""
from __future__ import annotations
import csv
import json
import math
import time
from pathlib import Path


def uart_baud_profile(baud, clock_hz=100_000_000):
    """Return the integer-divider baud generated by the current RTL."""
    if baud not in (115200, 921600, 2_000_000, 3_000_000):
        raise ValueError(f'unsupported baud rate: {baud}')
    divisor = (clock_hz + baud // 2) // baud
    actual = clock_hz / divisor
    return dict(requested_baud=baud, clock_hz=clock_hz, divider=divisor,
                actual_baud=actual, baud_error_percent=100 * (actual - baud) / baud)


class TransferMetrics:
    def __init__(self, baud, payload_bytes, resolution, pixel_format, image_id,
                 baseline_flush=False):
        self.started = time.monotonic()
        self.finished = None
        self.baud = baud
        self.total = payload_bytes
        self.resolution = resolution
        self.pixel_format = pixel_format
        self.image_id = image_id
        self.window = 1
        self.window_responses = 0
        self.window_sequence_errors = 0
        self.baseline_flush = baseline_flush
        self.attempts = []
        self.acked = {}
        self.rx_crc_errors = 0
        self.rx_invalid_frames = 0
        self.outcome = 'uploading'
        self.error = None
        self.data_started = None
        self.data_finished = None

    def begin_attempt(self, command, sequence, payload_bytes, wire_bytes, retry_count):
        now = time.monotonic()
        row = dict(command=command, sequence=sequence, payload_bytes=payload_bytes,
                   wire_bytes=wire_bytes, retry_count=retry_count,
                   send_start_time=now, send_finish_time=None, flush_finish_time=None,
                   ack_receive_time=None, outcome='pending', error_code=None)
        self.attempts.append(row)
        if command == 3 and self.data_started is None:
            self.data_started = now
        return row

    def acknowledge(self, row, error_code):
        now = time.monotonic()
        row.update(ack_receive_time=now, error_code=error_code,
                   outcome='ack' if error_code == 0 else 'device_error')
        if row['command'] == 3 and error_code == 0:
            self.acked[row['sequence']] = row['payload_bytes']
            self.data_finished = now

    def snapshot(self):
        elapsed = max((self.finished or time.monotonic()) - self.started, 1e-9)
        done = sum(self.acked.values())
        rows = [row for row in self.attempts if row['command'] == 3]
        rtts = sorted(row['ack_receive_time'] - row['send_start_time']
                      for row in rows if row['outcome'] == 'ack')
        wire_bytes = sum(row['wire_bytes'] for row in self.attempts
                         if row['send_finish_time'] is not None)
        data_elapsed = max((self.data_finished or self.data_started or self.started)
                           - (self.data_started or self.started), 1e-9)
        speed = done / elapsed
        write_seconds = sum(row['send_finish_time']-row['send_start_time']
                            for row in self.attempts if row['send_finish_time'] is not None)
        flush_seconds = sum(row['flush_finish_time']-row['send_finish_time']
                            for row in self.attempts if row['flush_finish_time'] is not None)
        post_write_ack_seconds = sum(row['ack_receive_time'] -
            (row['flush_finish_time'] or row['send_finish_time'])
            for row in self.attempts if row['ack_receive_time'] is not None)
        baud_profile = uart_baud_profile(self.baud)
        return dict(schema=2, outcome=self.outcome, error=self.error,
                    baud=self.baud, window=self.window, resolution=self.resolution,
                    pixel_format=self.pixel_format, image_id=self.image_id,
                    **baud_profile,
                    baseline_flush=self.baseline_flush, elapsed_s=elapsed,
                    total_payload_bytes=self.total, acknowledged_payload_bytes=done,
                    data_packets=len(self.acked), rtt_samples=len(rtts),
                    sufficient_1000_packets=len(self.acked) >= 1000,
                    payload_throughput_Bps=done/data_elapsed if done else 0,
                    effective_throughput_Bps=speed,
                    baud_efficiency_percent=100*speed*10/self.baud,
                    tx_wire_bytes=wire_bytes, tx_wire_time_estimate_s=wire_bytes*10/self.baud,
                    host_write_seconds=write_seconds, host_flush_seconds=flush_seconds,
                    host_post_write_ack_seconds=post_write_ack_seconds,
                    ack_rtt_min_ms=1000*rtts[0] if rtts else None,
                    ack_rtt_avg_ms=1000*sum(rtts)/len(rtts) if rtts else None,
                    ack_rtt_p95_ms=1000*rtts[math.ceil(.95*len(rtts))-1] if rtts else None,
                    ack_rtt_max_ms=1000*rtts[-1] if rtts else None,
                    retries=sum(row['retry_count'] > 0 for row in self.attempts),
                    ack_timeouts=sum(row['outcome'] == 'timeout' for row in self.attempts),
                    busy_responses=sum(row['error_code'] == 7 for row in self.attempts),
                    unexpected_sequence=self.window_sequence_errors+sum(row['error_code'] == 6 for row in self.attempts),
                    cumulative_ack_responses=self.window_responses,
                    whole_image_crc_errors=sum(row['error_code'] == 5 for row in self.attempts),
                    rx_crc_errors=self.rx_crc_errors, rx_invalid_frames=self.rx_invalid_frames,
                    fpga_packet_crc_errors=None, uart_framing_errors=None,
                    eta_s=0 if self.outcome == 'cached' else max(0, self.total-done)/speed if speed else None)

    def finish(self, outcome, error=None):
        self.finished = time.monotonic()
        self.outcome = outcome
        self.error = str(error) if error is not None else None

    def save(self, directory):
        directory = Path(directory)
        directory.mkdir(parents=True, exist_ok=True)
        stem = f'{time.strftime("%Y%m%d_%H%M%S")}_{self.resolution}_{self.image_id:08x}_{time.time_ns()}'
        report = directory / (stem + '.json')
        report.write_text(json.dumps(self.snapshot(), indent=2), encoding='utf-8')
        if self.attempts:
            with (directory / (stem + '.csv')).open('w', newline='', encoding='utf-8') as stream:
                writer = csv.DictWriter(stream, fieldnames=list(self.attempts[0]))
                writer.writeheader()
                writer.writerows(self.attempts)
        return report


def format_metrics(state):
    if state['outcome'] == 'cached':
        return f"IMG{state['resolution']}: READY (cache hit, no upload) | Baud {state['baud']} | Window {state['window']}"
    rtt = state['ack_rtt_avg_ms']
    eta = state['eta_s']
    percent = 100*state['acknowledged_payload_bytes']/max(state['total_payload_bytes'], 1)
    rtt_text = f'{rtt:.2f} ms' if rtt is not None else '--'
    eta_text = f'{eta:.1f}s' if eta is not None else '--'
    return (f"IMG{state['resolution']}: {percent:.1f}% | {state['elapsed_s']:.1f}s | "
            f"{state['effective_throughput_Bps']/1024:.1f} KiB/s | "
            f"Baud {state['baud']} (actual {state['actual_baud']:.0f}, "
            f"{state['baud_error_percent']:+.2f}%) | Efficiency {state['baud_efficiency_percent']:.1f}% | "
            f"ACK AVG {rtt_text} | "
            f"Window {state['window']} | Retries {state['retries']} | RX CRC {state['rx_crc_errors']} | "
            f"Image CRC {state['whole_image_crc_errors']} | FPGA CRC N/A | "
            f'ETA {eta_text}')
